<?php use App\UI\UI as U; $s=$data['sample']; $by = fn($k, $v) => (string)count(array_filter($s['stations'], fn($st) => $st[$k] === $v)); ?>
<?= U::heading('Registered stations','Station profiles, registration status and public availability.',U::btn('Export registry','','secondary','download',['data-export'=>'station-registry'])) ?>
<div class="mb-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Approved',$by('registration','Approved'),'check','green','Listed in the directory','Approved') ?><?= U::stat('Pending',$by('registration','Pending'),'clock','amber','Waiting for review','Pending') ?><?= U::stat('Open now',$by('availability','Open'),'store','blue','Taking orders today','Open') ?></div>
<section class="panel p-4 md:p-5"><div class="mb-4 max-w-lg"><?= U::field('Search station registry','station-search','','search',['icon'=>'search','data-search'=>'station-registry','placeholder'=>'Station or barangay']) ?></div>
<div class="overflow-x-auto"><table class="data-table" id="station-registry"><thead><tr><?php foreach(['Station','Registration','Availability','Drivers','Registered or applied','Details'] as $h): ?><th><?= $h ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($s['stations'] as $i=>$st): ?><tr data-search-row><td><span class="flex items-center gap-2.5"><span class="title-icon size-8"><?= U::icon('store','size-4') ?></span><span><span class="block font-semibold"><?= U::e($st['name']) ?></span><span class="flex items-center gap-1 text-xs text-muted"><?= U::icon('pin','size-3.5') ?><?= U::e($st['area']) ?></span></span></span></td><td><?= U::badge($st['registration'],$st['registration']==='Approved'?'green':($st['registration']==='Removed'?'gray':'amber')) ?></td><td><?= U::badge($st['availability'],$st['availability']==='Open'?'green':($st['availability']==='Maintenance'?'amber':'gray')) ?></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon('users','size-4 text-muted') ?><?= $st['drivers'] ?></span></td><td><span class="inline-flex items-center gap-1.5 whitespace-nowrap"><?= U::icon('calendar','size-4 text-muted') ?><?= U::e($st['date']) ?></span></td><td><?= U::btn('Details','','secondary','eye',['class'=>'btn-sm','data-dialog-open'=>'station-detail-'.$i]) ?></td></tr><?php endforeach; ?></tbody></table><p data-empty hidden class="p-5 text-center text-muted">No station registrations match.</p></div></section>
<?php foreach($s['stations'] as $i=>$st): ?><dialog id="station-detail-<?= $i ?>" aria-labelledby="station-detail-title-<?= $i ?>"><div class="flex items-start justify-between gap-4"><h2 id="station-detail-title-<?= $i ?>" class="section-title flex items-center gap-2.5"><span class="title-icon"><?= U::icon('store','size-5') ?></span><?= U::e($st['name']) ?></h2><button type="button" data-dialog-close aria-label="Close station details"><?= U::icon('close') ?></button></div>
<dl class="mt-4 space-y-1.5 text-sm"><?php foreach([['pin','Barangay',$st['area']],['home','Municipality','Hamtic, Antique'],['phone','Public contact',$st['contact']],['check','Registration',$st['registration']],['clock','Availability',$st['availability']],['users','Registered drivers',(string)$st['drivers']]] as [$icon,$dt,$dd]): ?><div class="flex items-center justify-between gap-3 rounded-lg bg-mist px-3 py-2"><dt class="flex items-center gap-2 text-muted"><?= U::icon($icon,'size-4 text-water') ?><?= U::e($dt) ?></dt><dd class="font-medium"><?= U::e($dd) ?></dd></div><?php endforeach ?></dl>
<?php if (empty($data['preview']) && in_array($st['status'] ?? '', ['approved', 'suspended'], true)): ?>
<form method="post" action="/super-admin/stations/status" class="mt-4 space-y-3 border-t border-line pt-4">
<input type="hidden" name="_token" value="<?= U::e(App\Core\Session::csrfToken()) ?>"><input type="hidden" name="request_key" value="<?= U::e(App\Controllers\LiveController::key()) ?>"><input type="hidden" name="station_id" value="<?= U::e($st['id']) ?>"><input type="hidden" name="expected_status" value="<?= U::e($st['status']) ?>">
<?= U::textarea('Reason (kept with the station record)', 'reason', '', ['id' => 'station-reason-' . $i, 'required' => true, 'minlength' => 3, 'maxlength' => 500, 'placeholder' => 'For example: permit expired, station closed']) ?>
<p class="text-xs text-muted">Suspend hides the station from customers and stops new orders; the owner can still finish open orders. Remove is final and only works when nothing is open; order history is kept.</p>
<div class="flex flex-wrap justify-end gap-2"><?= $st['status'] === 'suspended' ? U::btn('Reactivate', '', 'secondary', 'check', ['type' => 'submit', 'name' => 'status', 'value' => 'approved', 'class' => 'btn-sm']) : U::btn('Suspend', '', 'secondary', 'alert', ['type' => 'submit', 'name' => 'status', 'value' => 'suspended', 'class' => 'btn-sm', 'data-confirm' => 'Suspend ' . $st['name'] . '? Customers will no longer see it.']) ?><?= U::btn('Remove station', '', 'danger', 'close', ['type' => 'submit', 'name' => 'status', 'value' => 'archived', 'class' => 'btn-sm', 'data-confirm' => 'Remove ' . $st['name'] . ' for good? Its staff lose access. This cannot be undone.']) ?></div>
</form>
<?php endif ?></dialog><?php endforeach; ?>
